#include <iostream>
using namespace std;
int main() {
    int m, h;
    cin >> m >> h;
    int x = 100000 * m / (h * h);
    if (x < 180) {
        cout << "Underweight" << endl;
    } else if (x >= 240) {
        cout << "Overweight" << endl;
    } else {
        cout << "Normal" << endl;
    }
    return 0;
}
